local uci_helper = mapper("ucihelper")

local datausage_interface_ = {
	objectType = {
		name = 'rpc.datausage.interface.@.',
		access = 'readOnly',
		numEntriesParameter = "interfaceNumberOfEntries",
		minEntries = 0,
		maxEntries = math.huge,
		parameters = {
			tx_bytes_per_second = {
				access = "readOnly",
				type = "string"
			},
			rx_bytes_per_second = {
				access = "readOnly",
				type = "string"
			},
			tx_bytes_average = {
				access = "readOnly",
				type = "string"
			},
			rx_bytes_average = {
				access = "readOnly",
				type = "string"
			},
			tx_bytes_total = {
				access = "readOnly",
				type = "string"
			},
			rx_bytes_total = {
				access = "readOnly",
				type = "string"
			},
			reset = {
				access = "readWrite",
				type = "boolean"
			},
			usage_limit_reached = {
				access = "readOnly",
				type = "boolean"
			},
			usage_threshold_reached = {
				access = "readOnly",
				type = "boolean"
			},
			usage_limit_level = {
				access = "readOnly",
				type = "string"
			},
			usage_threshold_level = {
				access = "readOnly",
				type = "string"
			},
			interface_alias = {
				access = "readOnly",
				type = "string"
			},
			interface = {
				access = "readOnly",
				type = "string"
			},
			enabled = {
				access = "readOnly",
				type = "boolean"
			}
		}
	}
}

local conn = mapper("ubus").connect()
if not conn then
	return
end

local helper = require("mobiled.scripthelpers")

local function getall(mapping, key)
	local data = helper.getUbusData(conn, "datausage", "get", { interface = key }) or {}
	data.enabled = (not data.interface or data.interface == "") and "0" or "1"
	return data
end

local function get(mapping, paramName, key)
	return getall(mapping, key)[paramName]
end

local function set(mapping, paramName, paramValue, key)
	if paramName == "reset" then
		conn:call("datausage", "reset", { interface = key })
		return true
	end
end

local function datausageInterfaceEntries(mapping)
	local interfaces = {}
	local function cb(t)
		local ifname = t.interface or t.ifname
		if ifname and ifname ~= "" then
			table.insert(interfaces, { t['.name'], ifname })
		end
	end
	uci_helper.foreach_on_uci({
		config = "datausage",
		sectionname = "interface"
	}, cb)
	return interfaces
end

datausage_interface_.getall = getall
datausage_interface_.get = get
datausage_interface_.set = set
datausage_interface_.entries = datausageInterfaceEntries

register(datausage_interface_)
